using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable or AI:ApiKey in configuration.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient(modelId, apiKey));

builder.Services.AddSingleton<ResearchNotes>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var notes = host.Services.GetRequiredService<ResearchNotes>();

var tools = new[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(notes.AddNote),
    AIFunctionFactory.Create(notes.GetAllNotes),
};

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"🔍 Researching: {topic}\n");

var systemPrompt = """
    You are a research agent. Your goal is to research the given topic thoroughly.

    Follow these steps:
    1. Search the web for information about the topic (perform 2-3 searches with different queries)
    2. Take notes on the key findings from each search
    3. After gathering enough information, retrieve all your notes and produce a final summary

    Always take notes before moving on to the next search. Be thorough but concise.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Research this topic and provide a comprehensive summary: {topic}"),
};

var options = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [.. tools],
    ToolMode = ChatToolMode.Auto,
};

const int maxIterations = 15;

for (var i = 0; i < maxIterations; i++)
{
    var response = await chatClient.GetResponseAsync(messages, options);
    messages.AddMessages(response);

    if (response.Messages.Any(m => m.Role == ChatRole.Tool))
    {
        continue; // Tool calls were made and handled; loop again for the model's next step
    }

    // No tool calls — the agent has finished reasoning
    var finalContent = response.Messages
        .LastOrDefault(m => m.Role == ChatRole.Assistant)?.Text;

    if (!string.IsNullOrWhiteSpace(finalContent))
    {
        Console.WriteLine("═══════════════════════════════════════");
        Console.WriteLine("📋 RESEARCH SUMMARY");
        Console.WriteLine("═══════════════════════════════════════\n");
        Console.WriteLine(finalContent);
    }

    break;
}

Console.WriteLine("\n✅ Research complete.");

// --- Tools ---

/// <summary>Simulated web search tool that the agent uses to find information.</summary>
static class WebSearchTool
{
    [Description("Search the web for information on a query. Returns search result snippets.")]
    public static Task<string> SearchWebAsync(
        [Description("The search query")] string query)
    {
        // In production, integrate with Bing Search API, Google Custom Search, or similar.
        // This stub returns a placeholder so the app compiles and runs end-to-end.
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        var result = $"""
            Search results for: "{query}"

            1. [Placeholder result] — In a production scenario, this tool would call a real 
               search API (e.g., Bing Web Search) and return actual snippets. Configure a 
               search provider to get real results.
            2. [Placeholder result] — The agent will still demonstrate the full research 
               workflow: searching, taking notes, and summarizing findings.
            """;

        return Task.FromResult(result);
    }
}

/// <summary>Note-taking tool that lets the agent persist findings across reasoning steps.</summary>
sealed class ResearchNotes
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record key findings from search results.")]
    public string AddNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieve all saved research notes to use when writing the final summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📖 Retrieved {_notes.Count} note(s)");
        return string.Join("\n\n---\n\n", _notes.Select((n, i) => $"Note {i + 1}: {n}"));
    }
}

